<script setup>
import {ref,onMounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,addCart,yuan,run,date,notify} from '../lib'
import {ElMessageBox} from 'element-plus'
const route=useRoute(),router=useRouter(),p=ref(null),reviews=ref({items:[],total:0}),qty=ref(1),active=ref(''),page=ref(1)
async function load(){p.value=await api.get('/product/'+route.params.id);active.value=p.value.cover;await loadReviews()}
async function loadReviews(){reviews.value=await api.get('/review/product/'+route.params.id,{params:{page:page.value}})}
async function favorite(){if(!localStorage.getItem('userToken'))return router.push('/login');await api.post('/favorite/'+p.value.id);notify('收藏状态已更新，可在个人中心查看')}
async function report(r){if(!localStorage.getItem('userToken'))return router.push('/login');const {value}=await ElMessageBox.prompt('请填写举报依据，例如侵权、违法内容或泄露个人信息。','举报评价',{inputValidator:v=>!!v?.trim()||'请填写具体依据'});await api.post('/review/'+r.id+'/report',{reason:value});notify('已记录举报，等待商家处理')}
onMounted(()=>run(load));watch(()=>route.params.id,()=>{page.value=1;run(load)})
</script>
<template><div class="wrap section" v-if="p"><div class="breadcrumb"><RouterLink to="/shop">鲜花商城</RouterLink><span>/</span>{{p.name}}</div><section class="product-detail"><div class="detail-gallery"><img class="main-product-image" :src="active" :alt="p.name"/><div class="thumbnail-row"><button v-for="img in p.images" :key="img.id" @click="active=img.image_url" :class="{selected:active===img.image_url}"><img :src="img.image_url" alt="商品详情图片"/></button></div></div><div class="detail-copy"><span class="eyebrow">FLEUR · MADE WITH LOVE</span><h1>{{p.name}}</h1><p>{{p.description}}</p><div class="detail-price">¥ {{yuan(p.price)}} <small>/ 束</small></div><div class="rating"><span>★</span> {{Number(p.rating.rating).toFixed(1)}} <small>（{{p.rating.review_count}} 条真实购买评价）</small></div><dl><dt>花束规格</dt><dd><span class="specification">{{p.specification}}</span></dd><dt>库存状态</dt><dd>{{p.stock===0?'暂时售罄':p.stock<=10?'库存紧张 · 仅剩 '+p.stock+' 束':'现货 · 可售 '+p.stock+' 束'}}</dd><dt>购买数量</dt><dd><el-input-number v-model="qty" :min="1" :max="Math.min(p.stock||1,999)"/></dd></dl><div class="detail-actions"><button class="btn primary" :disabled="!p.stock" @click="run(()=>addCart(p,qty))"><Icon name="bag"/> {{p.stock?'加入购物袋':'暂时售罄'}}</button><button class="btn" @click="run(favorite)"><Icon name="heart"/> 收藏</button></div><RouterLink to="/ai" class="ai-mini"><Icon name="spark"/><span>想把心意写在花卡上？<b>试试 AI 专属祝福</b></span><Icon name="arrow"/></RouterLink><p class="subtle">每束花均为自然花材，形态与色泽可能略有差异。当前商城使用模拟交易。</p></div></section><section class="section"><div class="section-heading"><h2>收到花的故事</h2><span class="subtle">真实购买 · 用心分享</span></div><article v-for="r in reviews.items" :key="r.id" class="review-card"><div class="review-heading"><span class="avatar">{{r.nickname?.slice(0,1)}}</span><div><b>{{r.nickname}}</b><p class="rating">{{'★'.repeat(r.rating)}}<span class="subtle"> · {{date(r.create_time)}}</span></p></div></div><p>{{r.content}}</p><div class="review-images"><el-image v-for="img in r.images" :key="img.id" :src="img.image_url" :preview-src-list="r.images.map(i=>i.image_url)" fit="cover"/></div><div class="row-between"><p class="subtle">{{r.specification}}</p><button class="text-button muted" @click="run(()=>report(r))">举报评价</button></div><div v-if="r.reply" class="merchant-reply">花礼回复：{{r.reply}}</div></article><div v-if="!reviews.total" class="empty">还没有评价，期待第一份收到花的故事。</div><Pager :page="page" :total="reviews.total" @change="v=>{page=v;run(loadReviews)}"/></section></div></template>

